func _apply_maze_chest_reward(area: Area2D) -> void:
	if not _chapter_uses_maze_decisions(current_chapter):
		return
	var role := String(area.get_meta("maze_role", ""))
	if role == "exit_key":
		maze_keys = mini(MAZE_REQUIRED_KEYS, maze_keys + 1)
		var bonus := 10 if _maze_has_relic("lucky_key") else 0
		if bonus > 0:
			collected_coins += bonus
			wallet_coins += bonus
			_save_monster_companion_state()
		var key_name := _maze_key_name_for_chapter(current_chapter)
		message_label.text += " %s found%s." % [key_name, " +%d lucky coins" % bonus if bonus > 0 else ""]
		_show_status_popup(area.global_position + Vector2(0.0, -42.0), key_name, _chapter_accent_color(current_chapter))
	elif role == "relic" or role == "core":
		var relic := _roll_maze_relic()
		if not relic.is_empty():
			maze_relics.append(relic)
			if maze_relics.size() > MAZE_MAX_RELICS:
				maze_relics.pop_front()
			message_label.text += " Relic: %s." % _maze_relic_name(relic)
			_show_status_popup(area.global_position + Vector2(0.0, -42.0), _maze_relic_name(relic), Color(0.52, 1.0, 0.80))
		if role == "core":
			maze_risk += 1
	maze_risk += 0 if _maze_has_relic("silent_boots") else 1


func _roll_maze_relic() -> String:
	var pool: Array[String] = []
	for relic_def in MAZE_RELIC_DEFS:
		var relic_id := String(relic_def.get("id", ""))
		if not maze_relics.has(relic_id):
			pool.append(relic_id)
	if pool.is_empty():
		return ""
	return pool[rng.randi_range(0, pool.size() - 1)]


func _maze_relic_name(relic_id: String) -> String:
	for relic_def in MAZE_RELIC_DEFS:
		if String(relic_def.get("id", "")) == relic_id:
			return String(relic_def.get("name", relic_id))
	return relic_id


func _maze_has_relic(relic_id: String) -> bool:
	return maze_relics.has(relic_id)

