func _play_menu_enemy_walk(enemy: AnimatedSprite2D, direction: Vector2) -> void:
	var frames := enemy.sprite_frames
	if frames.has_animation("move_down"):
		var facing := "down"
		if absf(direction.x) > absf(direction.y):
			facing = "right" if direction.x > 0.0 else "left"
		else:
			facing = "down" if direction.y > 0.0 else "up"
		var animation := "move_%s" % facing
		enemy.play(animation if frames.has_animation(animation) else "move_down")
		return
	if frames.has_animation("move"):
		enemy.flip_h = direction.x < 0.0
		enemy.play("move")
		return
	if frames.has_animation("idle_down"):
		enemy.play("idle_down")


